1|// Pure upload contract: limits, ids, strict parsing, word counts, part
2|// splitting, key builders, error codes. No env reads, no network, no
3|// secrets. Server modules in server/uploads/ build on it.
4|import type { RawSection } from "./clean-types";
5|import { FREE_BOOK_MAX_WORDS } from "./upload-policy";
6|
7|export { FREE_BOOK_MAX_WORDS };
8|
9|// BYOK books pay with the reader's key, so the ceiling is the 4 MB body.
10|export const BYOK_BOOK_MAX_WORDS = 400_000;
11|// Under the Hobby 4.5 MB request limit with JSON overhead to spare.
12|export const UPLOAD_MAX_BODY_BYTES = 4_000_000;
13|export const UPLOAD_STEP_BODY_BYTES = 4096;
14|export const UPLOAD_MAX_SECTIONS = 600;
15|export const UPLOAD_MAX_BLOCKS_PER_SECTION = 2000;
16|export const UPLOAD_MAX_BLOCK_CHARS = 20_000;
17|export const UPLOAD_MAX_TITLE_CHARS = 300;
18|export const UPLOAD_MAX_CHAPTERS = 500;
19|// One part fits one segment call plus its scenes inside the route budget.
20|export const UPLOAD_MAX_PART_PARAGRAPHS = 150;
21|// Global free-upload spend: USD 1 per UTC day, shared across readers.
22|export const UPLOAD_DAILY_SPEND_CAP_MICRO = 1_000_000;
23|// Ceiling on the per-book hold; the real cost reconciles at finalize.
24|export const UPLOAD_RESERVE_MICRO = 250_000;
25|export const UPLOAD_RESERVE_FLOOR_MICRO = 50_000;
26|export const UPLOAD_RESERVE_PER_PART_MICRO = 5_000;
27|
28|// Measured: a 3,955-word book cost USD 0.0027 (~0.7 micro/word). The hold
29|// prices 1 micro/word plus 5k micro/part for the judge and retries, so a
30|// 50k-word book holds ~110k micro, well under the USD 1/day cap.
31|export function uploadReserveMicro(parts: number, words: number): number {
32|  const sized = Math.max(UPLOAD_RESERVE_FLOOR_MICRO, parts * UPLOAD_RESERVE_PER_PART_MICRO + Math.max(0, Math.round(words)));
33|  return Math.min(UPLOAD_RESERVE_MICRO, sized);
34|}
35|export const UPLOAD_TTL_DAYS = 30;
36|export const UPLOAD_JOB_TTL_SEC = 30 * 24 * 3600;
37|export const UPLOAD_MODEL = "muse-spark-1.3-contributor";
38|export const UPLOAD_JEV_MODEL = "jev-1.14.0";
39|
40|export type UploadErrorCode =
41|  | "too_long"
42|  | "daily_books_reached"
43|  | "daily_budget_reached"
44|  | "human_required"
45|  | "bad_request"
46|  | "unavailable"
47|  | "not_found"
48|  | "expired";
49|
50|export const UPLOAD_MESSAGES: Record<UploadErrorCode, string> = {
51|  too_long: "This one is longer than the free book covers. With your own Meta key you can still read it with a soundtrack.",
52|  daily_books_reached: "That's two free books for today. More tomorrow, or use your own key for this one.",
53|  daily_budget_reached: "So many people loved this that we've run out of credits to share today. Try again tomorrow, or bring your own key.",
54|  human_required: "One quick check that you're a person first.",
55|  bad_request: "Something went wrong there. Try again?",
56|  unavailable: "We couldn't process this book right now. Try again in a moment.",
57|  not_found: "We couldn't find this upload. It may have expired.",
58|  expired: "This upload expired after 30 days. Upload the book again to read it.",
59|};
60|
61|export const UPLOAD_HTTP_STATUS: Record<UploadErrorCode, number> = {
62|  too_long: 413,
63|  daily_books_reached: 429,
64|  daily_budget_reached: 503,
65|  human_required: 403,
66|  bad_request: 400,
67|  unavailable: 503,
68|  not_found: 404,
69|  expired: 410,
70|};
71|
72|export class UploadValidationError extends Error {
73|  constructor(message = "invalid upload request") {
74|    super(message);
75|    this.name = "UploadValidationError";
76|  }
77|}
78|
79|// 128-bit random, base64url without padding (22 chars), prefixed so ids
80|// never collide with paragraph or scene ids.
81|export const UPLOAD_ID_RE = /^u-[A-Za-z0-9_-]{22}$/;
82|
83|const B64URL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
84|
85|export function newUploadId(): string {
86|  const bytes = new Uint8Array(16);
87|  globalThis.crypto.getRandomValues(bytes);
88|  let out = "u-";
89|  let bits = 0;
90|  let value = 0;
91|  for (const byte of bytes) {
92|    value = (value << 8) | byte;
93|    bits += 8;
94|    while (bits >= 6) {
95|      bits -= 6;
96|      out += B64URL[(value >> bits) & 63];
97|    }
98|  }
99|  if (bits > 0) out += B64URL[(value << (6 - bits)) & 63];
100|  return out;
101|}
102|
103|export function isUploadId(id: unknown): id is string {
104|  return typeof id === "string" && UPLOAD_ID_RE.test(id);
105|}
106|
107|export function parseUploadId(id: unknown): string {
108|  if (!isUploadId(id)) throw new UploadValidationError("bad upload id");
109|  return id;
110|}
111|
112|export interface UploadCreateBody {
113|  title: string;
114|  author: string | null;
115|  sections: RawSection[];
116|  turnstileToken?: string;
117|}
118|
119|function isRecord(json: unknown): json is Record<string, unknown> {
120|  return typeof json === "object" && json !== null && !Array.isArray(json);
121|}
122|
123|function isStringArray(value: unknown, maxItems: number, maxChars: number): value is string[] {
124|  return (
125|    Array.isArray(value) &&
126|    value.length <= maxItems &&
127|    value.every((t) => typeof t === "string" && t.length <= maxChars)
128|  );
129|}
130|
131|// Strict parse at the trust boundary: exact fields only, defensive caps on
132|// every list and string, so a bad client cannot push unbounded work in.
133|export function parseUploadCreate(json: unknown): UploadCreateBody {
134|  if (!isRecord(json)) throw new UploadValidationError();
135|  const keys = Object.keys(json).sort().join(",");
136|  const base = "author,sections,title";
137|  if (keys !== base && keys !== "sections,title" && keys !== `${base},turnstileToken` && keys !== "sections,title,turnstileToken") {
138|    throw new UploadValidationError();
139|  }
140|  const title = json.title;
141|  if (typeof title !== "string" || title.trim().length === 0 || title.length > UPLOAD_MAX_TITLE_CHARS) {
142|    throw new UploadValidationError();
143|  }
144|  const author = json.author;
145|  if (author !== undefined && author !== null && (typeof author !== "string" || author.length > UPLOAD_MAX_TITLE_CHARS)) {
146|    throw new UploadValidationError();
147|  }
148|  const sections = json.sections;
149|  if (!Array.isArray(sections) || sections.length === 0 || sections.length > UPLOAD_MAX_SECTIONS) {
150|    throw new UploadValidationError();
151|  }
152|  const parsed: RawSection[] = sections.map((sec) => {
153|    if (!isRecord(sec)) throw new UploadValidationError();
154|    if (Object.keys(sec).sort().join(",") !== "blocks,docTitle,href,id,linear,navLabel,types") {
155|      throw new UploadValidationError();
156|    }
157|    if (typeof sec.id !== "string" || sec.id.length === 0 || sec.id.length > UPLOAD_MAX_TITLE_CHARS) {
158|      throw new UploadValidationError();
159|    }
160|    if (typeof sec.href !== "string" || sec.href.length > 2000) throw new UploadValidationError();
161|    if (typeof sec.linear !== "boolean") throw new UploadValidationError();
162|    if (!isStringArray(sec.types, 20, 100)) throw new UploadValidationError();
163|    for (const key of ["docTitle", "navLabel"] as const) {
164|      const value = sec[key];
165|      if (value !== null && (typeof value !== "string" || value.length > UPLOAD_MAX_TITLE_CHARS)) {
166|        throw new UploadValidationError();
167|      }
168|    }
169|    if (!Array.isArray(sec.blocks) || sec.blocks.length > UPLOAD_MAX_BLOCKS_PER_SECTION) {
170|      throw new UploadValidationError();
171|    }
172|    const blocks = sec.blocks.map((block) => {
173|      if (!isRecord(block)) throw new UploadValidationError();
174|      if (Object.keys(block).sort().join(",") !== "heading,text") throw new UploadValidationError();
175|      if (typeof block.text !== "string" || block.text.length > UPLOAD_MAX_BLOCK_CHARS) {
176|        throw new UploadValidationError();
177|      }
178|      if (typeof block.heading !== "boolean") throw new UploadValidationError();
179|      return { text: block.text, heading: block.heading };
180|    });
181|    return {
182|      id: sec.id,
183|      href: sec.href,
184|      linear: sec.linear,
185|      types: sec.types as string[],
186|      docTitle: sec.docTitle as string | null,
187|      navLabel: sec.navLabel as string | null,
188|      blocks,
189|    };
190|  });
191|  const out: UploadCreateBody = {
192|    title: title.trim(),
193|    author: typeof author === "string" && author.trim() !== "" ? author.trim() : null,
194|    sections: parsed,
195|  };
196|  if (json.turnstileToken !== undefined) {
197|    if (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048) {
198|      throw new UploadValidationError();
199|    }
200|    out.turnstileToken = json.turnstileToken;
201|  }
202|  return out;
203|}
204|
205|// Same word shape the browser counts for routing, so the server enforces
206|// the limit the client promised.
207|const WORD_RE = /[\p{L}\p{N}]+(?:['’][\p{L}]+)*/gu;
208|
209|export function countWords(text: string): number {
210|  WORD_RE.lastIndex = 0;
211|  let count = 0;
212|  let match: RegExpExecArray | null;
213|  while ((match = WORD_RE.exec(text)) !== null && match[0].length > 0) count += 1;
214|  return count;
215|}
216|
217|export function countChapterWords(chapters: { paragraphs: string[] }[]): number {
218|  let total = 0;
219|  for (const chapter of chapters) {
220|    for (const paragraph of chapter.paragraphs) total += countWords(paragraph);
221|  }
222|  return total;
223|}
224|
225|export interface UploadPart {
226|  ch: number;
227|  part: number;
228|  startN: number;
229|  endN: number;
230|}
231|
232|export function partKey(part: Pick<UploadPart, "ch" | "part">): string {
233|  return `ch${part.ch}p${part.part}`;
234|}
235|
236|// Long chapters split into paragraph windows so one step stays in budget.
237|export function splitChapterParts(
238|  chapters: { ch: number; start_n: number; end_n: number }[],
239|  maxParas: number = UPLOAD_MAX_PART_PARAGRAPHS,
240|): UploadPart[] {
241|  const parts: UploadPart[] = [];
242|  for (const chapter of chapters) {
243|    let part = 1;
244|    for (let start = chapter.start_n; start <= chapter.end_n; start += maxParas, part += 1) {
245|      parts.push({ ch: chapter.ch, part, startN: start, endN: Math.min(start + maxParas - 1, chapter.end_n) });
246|    }
247|  }
248|  return parts;
249|}
250|
251|export function parseStepBody(json: unknown): { chapter?: number; turnstileToken?: string } {
252|  if (!isRecord(json)) throw new UploadValidationError();
253|  const keys = Object.keys(json).sort().join(",");
254|  if (keys !== "" && keys !== "chapter" && keys !== "turnstileToken" && keys !== "chapter,turnstileToken") {
255|    throw new UploadValidationError();
256|  }
257|  const out: { chapter?: number; turnstileToken?: string } = {};
258|  if (json.chapter !== undefined) {
259|    if (typeof json.chapter !== "number" || !Number.isSafeInteger(json.chapter) || json.chapter < 1) {
260|      throw new UploadValidationError();
261|    }
262|    out.chapter = json.chapter;
263|  }
264|  if (json.turnstileToken !== undefined) {
265|    if (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048) {
266|      throw new UploadValidationError();
267|    }
268|    out.turnstileToken = json.turnstileToken;
269|  }
270|  return out;
271|}
272|
273|// Private Blob layout; the id is unguessable, URLs never leave the server.
274|export function uploadBookPath(id: string): string {
275|  return `uploads/${id}/book.json`;
276|}
277|
278|export function uploadPartPath(id: string, part: string): string {
279|  return `uploads/${id}/part-${part}.json`;
280|}
281|
282|export function uploadAnalysisPath(id: string): string {
283|  return `uploads/${id}/analysis.json`;
284|}
285|
286|export function uploadDailySpendKey(day: string): string {
287|  return `upload:spend:daily:${day}`;
288|}

