60|function defaultSleep(ms: number, signal?: AbortSignal): Promise<void> {
61|  return new Promise((resolve, reject) => {
62|    const timer = setTimeout(() => {
63|      signal?.removeEventListener("abort", onAbort);
64|      resolve();
65|    }, ms);
66|    const onAbort = (): void => {
67|      clearTimeout(timer);
68|      reject(signal?.reason ?? new Error("aborted"));
69|    };
70|    if (signal?.aborted) {
71|      onAbort();
