126|// Drives create (once: every attempt can take quota) then steps until
127|// done. Resuming reuses the job id, so progress continues from the
128|// server's done/total. Steps retry network failures and uncoded 5xx.
129|export async function driveUpload(opts: DriveOpts): Promise<{ id: string; chapters: number }> {
130|  const fetchFn = opts.fetchFn ?? fetch;
131|  const sleep = opts.sleep ?? ((ms: number) => defaultSleep(ms, opts.signal));
132|  let token = opts.token;
133|  let jobId = opts.jobId;
134|  let chapters = 0;
135|  if (!jobId) {
136|    let res: Response;
137|    try {
138|      res = await fetchFn("/api/uploads", {
139|        method: "POST",
140|        headers: headersFor(opts.key),
141|        body: JSON.stringify({
142|          title: opts.title,
143|          author: opts.author,
144|          sections: opts.sections,
145|          ...(token ? { turnstileToken: token } : {}),
146|        }),
147|        signal: opts.signal,
148|      });
149|    } catch (err) {
150|      if (opts.signal?.aborted) throw err;
151|      throw new UploadFlowError("network", null);
152|    }
153|    token = null; // Single use: later steps ride the human cookie. secret-scan:allow (not a secret)
154|    const json = await readJson(res);
155|    const body = (typeof json === "object" && json !== null ? json : {}) as Record<string, unknown>;
156|    if (body.status === "error" && isCode(body.code)) throw new UploadFlowError(body.code, null);
157|    if (
158|      body.status !== "created" ||
159|      !isUploadId(body.id) ||
160|      !isCount(body.chapters) ||
161|      !isCount(body.parts)
162|    ) {
163|      throw new UploadFlowError("unavailable", null);
164|    }
165|    jobId = body.id;
166|    chapters = body.chapters;
167|    opts.onProgress?.({ jobId, done: 0, total: body.parts, chapters });
168|  }
169|  for (;;) {
170|    let attempt = 0;
171|    for (;;) {
172|      try {
173|        const outcome = await attemptStep(opts, jobId, token, chapters);
174|        token = null;
175|        opts.onProgress?.(outcome.progress);
176|        if (outcome.done) return { id: jobId, chapters };
177|        break;
178|      } catch (err) {
179|        if (opts.signal?.aborted) throw err;
180|        // Only the retryable shape loops; coded errors fail at once.
181|        const retryable = err instanceof UploadFlowError && err.code === "network";
182|        if (!retryable || attempt >= STEP_RETRIES) throw err;
183|        await sleep(BACKOFF_MS[attempt] ?? 2000);
184|        attempt += 1;
185|      }
186|    }
187|  }
