100|  let res: Response;
101|  try {
102|    res = await fetchFn(`/api/uploads/${jobId}/step`, {
103|      method: "POST",
104|      headers: headersFor(opts.key),
105|      body: JSON.stringify(token ? { turnstileToken: token } : {}),
106|      signal: opts.signal,
107|    });
108|  } catch (err) {
109|    if (opts.signal?.aborted) throw err;
110|    throw new UploadFlowError("network", jobId);
111|  }
112|  const json = await readJson(res);
113|  const body = (typeof json === "object" && json !== null ? json : {}) as Record<string, unknown>;
114|  if (body.status === "error" && isCode(body.code)) {
115|    throw new UploadFlowError(body.code, jobId);
116|  }
117|  if (res.status >= 500) throw new UploadFlowError("network", jobId);
118|  if ((body.status === "working" || body.status === "done") && isCount(body.done) && isCount(body.total)) {
