147|        signal: opts.signal,
148|      });
149|    } catch (err) {
150|      if (opts.signal?.aborted) throw err;
151|      throw new UploadFlowError("network", null);
152|    }
153|    token = null; // Single use: later steps ride the human cookie. secret-scan:allow (not a secret)
154|    const json = await readJson(res);
155|    const body = (typeof json === "object" && json !== null ? json : {}) as Record<string, unknown>;
156|    if (body.status === "error" && isCode(body.code)) throw new UploadFlowError(body.code, null);
