166|    chapters = body.chapters;
167|    opts.onProgress?.({ jobId, done: 0, total: body.parts, chapters });
168|  }
169|  for (;;) {
170|    let attempt = 0;
171|    for (;;) {
172|      try {
173|        const outcome = await attemptStep(opts, jobId, token, chapters);
174|        token = null;
175|        opts.onProgress?.(outcome.progress);
176|        if (outcome.done) return { id: jobId, chapters };
177|        break;
178|      } catch (err) {
