1|// UI hint only; the server enforces the real 2/day quota. Counts how
2|// many free books started today (UTC), so the route matches the server.
3|const KEY = "lectoria.freeBooks.v2";
4|
5|export function utcDay(now: Date = new Date()): string {
6|  return now.toISOString().slice(0, 10);
7|}
8|
9|export function getFreeBooksToday(now: Date = new Date()): number {
10|  try {
11|    const raw = window.localStorage.getItem(KEY);
12|    if (!raw) return 0;
13|    const parsed = JSON.parse(raw) as { day?: unknown; count?: unknown };
14|    if (parsed.day !== utcDay(now)) return 0;
15|    if (typeof parsed.count !== "number" || !Number.isInteger(parsed.count) || parsed.count < 0) {
16|      return 0;
17|    }
18|    return parsed.count;
19|  } catch {
20|    return 0; // Bad JSON or blocked storage: route as if none used.
21|  }
22|}
23|
24|export function countFreeBookToday(now: Date = new Date()): void {
25|  try {
26|    window.localStorage.setItem(KEY, JSON.stringify({ day: utcDay(now), count: getFreeBooksToday(now) + 1 }));
27|  } catch {
28|    // Private mode or blocked storage: the hint just does not stick.
29|  }
