43|
44|// Same ordinals and hash input as the Gutenberg path, without the
45|// Gutenberg source block: uploads are reader books, not shelf books.
46|export function buildUploadBook(
47|  id: string,
48|  title: string,
49|  author: string | null,
50|  drafts: { title: string; paragraphs: string[] }[],
51|): UploadBook {
52|  const chapters: Chapter[] = [];
53|  const paragraphs: Paragraph[] = [];
54|  let n = 0;
55|  drafts.forEach((draft, index) => {
56|    const ch = index + 1;
57|    const start_n = n + 1;
58|    draft.paragraphs.forEach((text, k) => {
59|      n += 1;
60|      paragraphs.push({ id: paragraphId(ch, k + 1), ch, n, text });
61|    });
62|    chapters.push({ ch, title: draft.title, start_n, end_n: n });
63|  });
64|  const textVersion = `sha256:${createHash("sha256").update(canonicalLines(paragraphs)).digest("hex")}`;
65|  // The reader prints the author, so a missing one becomes Unknown here.
66|  return { id, title, author: author ?? "Unknown", chapters, paragraphs, textVersion };
67|}
