69|export interface CreateArgs {
70|  kv: KV;
71|  store: UploadStore;
72|  meta: MetaClient;
73|  body: UploadCreateBody;
74|  path: "free" | "byok";
75|  anonId: string;
76|  day: string;
77|  quotaKeys: { ip: string; anon: string } | null;
78|  spendCapMicro: number;
