82|// Total wall clock the cleaning judge may take inside the create request.
83|// The per-call timeout still applies beneath; retries that outlast this
84|// just lose, and the book keeps its deterministic chapters.
85|export const CLEAN_JUDGE_BUDGET_MS = 25_000;
86|
87|function judgeWithBudget(judge: Judge, ms: number): Judge {
88|  return async (input) => {
89|    let timer: ReturnType<typeof setTimeout> | undefined;
90|    const expired = new Promise<null>((resolve) => {
91|      timer = setTimeout(() => resolve(null), ms);
92|    });
93|    try {
94|      return await Promise.race([judge(input), expired]);
95|    } finally {
96|      if (timer !== undefined) clearTimeout(timer);
97|    }
98|  };
99|}
