101|// Parts estimate for sizing the hold: the judge runs after the reserve,
102|// so count from the deterministic preview with the same splitter.
103|function estimatePartCount(chapters: { paragraphs: string[] }[]): number {
104|  let n = 0;
105|  const pseudo = chapters.map((chapter, index) => {
106|    const start = n + 1;
107|    n += chapter.paragraphs.length;
108|    return { ch: index + 1, start_n: start, end_n: n };
109|  });
110|  return splitChapterParts(pseudo).length;
