126|  let quotaTaken = false;
127|  let reservation: SpendReservation | null = null;
128|  let reservedMicro = 0;
129|  try {
130|    if (args.quotaKeys) {
131|      const taken = await takeDualQuota(args.kv, args.quotaKeys, {
132|        limit: args.path === "free" ? FREE_BOOKS_PER_PERSON : BYOK_UPLOADS_PER_PERSON,
133|        ttlSec: BOOK_QUOTA_TTL_SEC,
134|      });
135|      if (!taken.ok) throw new UploadFailure("daily_books_reached");
136|      quotaTaken = true;
137|      if (args.path === "free") {
138|        reservedMicro = uploadReserveMicro(estimatePartCount(preview.chapters), previewWords);
139|        const spent = await reserveSpend(args.kv, {
140|          amountMicro: reservedMicro,
141|          day: args.day,
142|          spendCapMicro: args.spendCapMicro,
143|          dailySpendCapMicro: UPLOAD_DAILY_SPEND_CAP_MICRO,
144|          dailyKey: uploadDailySpendKey(args.day),
145|        });
146|        if (!spent.ok) throw new UploadFailure("daily_budget_reached");
147|        reservation = spent.reservation;
148|      }
149|    }
