5|// Per-person quota: 5 new images per day, counted by hashed IP and by
6|// anonymous cookie, whichever runs out first. Day keys are UTC dates.
7|export function utcDay(now: Date = new Date()): string {
8|  return now.toISOString().slice(0, 10);
9|}
