11|export function hashIp(ip: string, salt: string): string {
12|  return createHmac("sha256", salt).update(ip).digest("hex");
13|}
14|
15|// Quota input for the IP-side key: a real IP is shared across cookies,
16|// while "unknown" falls back to per-cookie separation so one client
17|// cannot exhaust the bucket for all the others.
18|// Bucket IPv6 by /64 prefix so one client rotating interface IDs shares one quota bucket.
19|export function ipBucket(ip: string, anonId: string): string {
20|  if (ip === "unknown") return `unknown:${anonId}`;
21|  return canonicalIpBucket(ip);
22|}
23|
24|// Canonical bucket form for IPv6 is zero-padded lowercase "xxxx:xxxx:xxxx:xxxx::/64" (first 4 hextets).
25|function canonicalIpBucket(ip: string): string {
26|  let v = ip;
27|  if (v.startsWith("[") && v.endsWith("]")) v = v.slice(1, -1);
28|  const pct = v.indexOf("%");
29|  if (pct !== -1) v = v.slice(0, pct);
30|  if (isIPv4(v)) return v;
31|  if (!isIPv6(v)) return ip;
32|  if (v.includes(".")) {
33|    const i = v.lastIndexOf(":");
34|    const o = v.slice(i + 1).split(".").map(Number);
35|    v = `${v.slice(0, i + 1)}${((o[0] ?? 0) * 256 + (o[1] ?? 0)).toString(16)}:${((o[2] ?? 0) * 256 + (o[3] ?? 0)).toString(16)}`;
36|  }
37|  const [l = "", r] = v.split("::");
38|  const a = l ? l.split(":") : [];
39|  const b = r === undefined ? [] : r ? r.split(":") : [];
40|  const full =
41|    r === undefined ? v.split(":") : [...a, ...Array<string>(8 - a.length - b.length).fill("0"), ...b];
42|  const g = full.map((p) => parseInt(p, 16));
43|  if (g.slice(0, 5).every((n) => n === 0) && g[5] === 0xffff)
44|    return `${(g[6] ?? 0) >> 8}.${(g[6] ?? 0) & 255}.${(g[7] ?? 0) >> 8}.${(g[7] ?? 0) & 255}`;
45|  const h = (n: number | undefined) => (n ?? 0).toString(16).padStart(4, "0");
