1|import "server-only";
2|import { createHmac } from "node:crypto";
3|import { isIPv4, isIPv6 } from "node:net";
4|
5|// Per-person quota: 5 new images per day, counted by hashed IP and by
6|// anonymous cookie, whichever runs out first. Day keys are UTC dates.
7|export function utcDay(now: Date = new Date()): string {
8|  return now.toISOString().slice(0, 10);
9|}
10|
11|export function hashIp(ip: string, salt: string): string {
12|  return createHmac("sha256", salt).update(ip).digest("hex");
13|}
14|
15|// Quota input for the IP-side key: a real IP is shared across cookies,
16|// while "unknown" falls back to per-cookie separation so one client
17|// cannot exhaust the bucket for all the others.
18|// Bucket IPv6 by /64 prefix so one client rotating interface IDs shares one quota bucket.
19|export function ipBucket(ip: string, anonId: string): string {
20|  if (ip === "unknown") return `unknown:${anonId}`;
21|  return canonicalIpBucket(ip);
22|}
23|
24|// Canonical bucket form for IPv6 is zero-padded lowercase "xxxx:xxxx:xxxx:xxxx::/64" (first 4 hextets).
25|function canonicalIpBucket(ip: string): string {
26|  let v = ip;
27|  if (v.startsWith("[") && v.endsWith("]")) v = v.slice(1, -1);
28|  const pct = v.indexOf("%");
29|  if (pct !== -1) v = v.slice(0, pct);
30|  if (isIPv4(v)) return v;
31|  if (!isIPv6(v)) return ip;
32|  if (v.includes(".")) {
33|    const i = v.lastIndexOf(":");
34|    const o = v.slice(i + 1).split(".").map(Number);
35|    v = `${v.slice(0, i + 1)}${((o[0] ?? 0) * 256 + (o[1] ?? 0)).toString(16)}:${((o[2] ?? 0) * 256 + (o[3] ?? 0)).toString(16)}`;
36|  }
37|  const [l = "", r] = v.split("::");
38|  const a = l ? l.split(":") : [];
39|  const b = r === undefined ? [] : r ? r.split(":") : [];
40|  const full =
41|    r === undefined ? v.split(":") : [...a, ...Array<string>(8 - a.length - b.length).fill("0"), ...b];
42|  const g = full.map((p) => parseInt(p, 16));
43|  if (g.slice(0, 5).every((n) => n === 0) && g[5] === 0xffff)
44|    return `${(g[6] ?? 0) >> 8}.${(g[6] ?? 0) & 255}.${(g[7] ?? 0) >> 8}.${(g[7] ?? 0) & 255}`;
45|  const h = (n: number | undefined) => (n ?? 0).toString(16).padStart(4, "0");
46|  return `${h(g[0])}:${h(g[1])}:${h(g[2])}:${h(g[3])}::/64`;
47|}
48|
49|// First live platform header wins: the Vercel forwarding header, then
50|// the single-IP real-ip header, then the first x-forwarded-for entry.
51|// Each candidate is trimmed and loosely validated (no spaces or commas,
52|// at most 64 chars); anything else falls through to "unknown".
53|export function clientIp(headers: Headers): string {
54|  const single = (name: string): string | null => clean(headers.get(name));
55|  return (
56|    single("x-vercel-forwarded-for") ??
57|    single("x-real-ip") ??
58|    clean(headers.get("x-forwarded-for")?.split(",")[0]) ??
59|    "unknown"
60|  );
61|}
62|
63|function clean(raw: string | null | undefined): string | null {
64|  if (raw === null || raw === undefined) return null;
65|  const ip = raw.trim();
66|  if (ip === "" || ip.length > 64 || /[\s,]/.test(ip)) return null;
67|  return ip;
68|}
69|
70|// Reject cross-site simple-request CSRF: a third-party page can make a
71|// visitor's browser send a `mode:"no-cors"` `text/plain` POST (a CORS
72|// simple request, no preflight), spending owner budget and draining the
73|// shared daily spend cap from many IPs. Our own clients always send
74|// `Content-Type: application/json` from the same origin, so anything
75|// else is not ours. Pure: reads headers and the request URL only, and
76|// never logs header values.
77|export function rejectsCrossSite(headers: Headers, requestUrl: string): boolean {
78|  const mediaType = headers
79|    .get("content-type")
80|    ?.split(";")[0]
81|    ?.trim()
82|    .toLowerCase();
83|  if (mediaType !== "application/json") return true;
84|
85|  const fetchSite = headers.get("sec-fetch-site")?.trim().toLowerCase();
86|  if (fetchSite !== null && fetchSite !== undefined && fetchSite !== "") {
87|    if (fetchSite !== "same-origin" && fetchSite !== "none") return true;
88|  }
89|
90|  const origin = headers.get("origin")?.trim();
91|  if (origin !== null && origin !== undefined && origin !== "") {
92|    if (origin === "null") return true;
93|    let originHost: string;
94|    try {
95|      originHost = new URL(origin).host.toLowerCase();
96|    } catch {
97|      return true;
98|    }
99|    const forwarded = headers.get("x-forwarded-host")?.split(",")[0]?.trim();
100|    const hostHeader = headers.get("host")?.trim();
101|    let requestHost = (forwarded || hostHeader || "").toLowerCase();
102|    if (!requestHost) {
103|      try {
104|        requestHost = new URL(requestUrl).host.toLowerCase();
105|      } catch {
106|        return true;
107|      }
108|    }
109|    if (originHost !== requestHost) return true;
110|  }
111|
112|  return false;
113|}

