32|export function readUploadEnv(from: NodeJS.ProcessEnv = process.env): UploadEnv {
33|  const candidate = usable(from.UPSTASH_REDIS_REST_URL) ?? usable(from.KV_REST_API_URL);
34|  const upstashUrl = candidate?.startsWith("https://") ? candidate : undefined;
35|  const upstashToken = usable(from.UPSTASH_REDIS_REST_TOKEN) ?? usable(from.KV_REST_API_TOKEN);
36|  const missing = [
37|    upstashUrl ? null : URL_NAMES,
38|    upstashToken ? null : TOKEN_NAMES,
39|    ...REQUIRED.filter((k) => !usable(from[k])),
40|  ].filter((m): m is string => m !== null);
41|  if (missing.length > 0) throw new Error(`missing upload env: ${missing.join(",")}`);
42|  const jevKey = usable(from.JEV_API_KEY);
43|  return {
