5|import type { RawSection } from "@/core/clean-types";
6|import type { JevClient, JevResult } from "../../pipeline/jev";
7|import type { MetaClient, MetaUsage } from "../../pipeline/meta";
8|import type { UploadEnv } from "./env";
9|
10|export { createMemoryKV };
11|export type { KV };
12|export { memoryStore, type MemoryStore } from "./memory";
13|
14|export function testEnv(over: Partial<UploadEnv> = {}): UploadEnv {
15|  return {
16|    upstashUrl: "https://upstash.test",
17|    upstashToken: "upstash-token",
18|    uploadsToken: "uploads-token",
19|    metaKey: "owner-meta-key",
20|    sessionSecret: "session-secret-for-tests-only",
21|    ipSalt: "ip-salt-for-tests",
22|    spendCapMicro: 10_000_000,
23|    ...over,
24|  };
25|}
26|
27|export interface MetaCall {
28|  system: string;
29|  user: string;
30|  schemaName: string;
31|}
32|
33|const USAGE = { promptTokens: 1000, cachedTokens: 100, completionTokens: 100 };
34|
35|export function scriptedMeta(
36|  respond: (call: MetaCall) => unknown,
37|  usage: { promptTokens: number; cachedTokens: number; completionTokens: number } = USAGE,
38|): MetaClient & { calls: MetaCall[] } {
39|  const calls: MetaCall[] = [];
40|  return {
41|    calls,
42|    model: "muse-spark-1.3-contributor",
43|    async completeJson(input: { system: string; user: string; schemaName: string; schema: Record<string, unknown> }): Promise<MetaUsage> {
44|      const call = { system: input.system, user: input.user, schemaName: input.schemaName };
45|      calls.push(call);
46|      return { data: respond(call), ...usage };
47|    },
48|  };
49|}
