1|import "server-only";
2|import { parseCapUsd, turnstilePair, usable } from "@/server/guard/env";
3|import type { TurnstilePair } from "@/server/guard/env";
4|
5|// Upload env, read once per request. Jev is optional: without a usable key
6|// the free path classifies with the contributor model alone. Missing
7|// required env means 503 unavailable, never unauthenticated spend.
8|export interface UploadEnv extends TurnstilePair {
9|  upstashUrl: string;
10|  upstashToken: string;
11|  uploadsToken: string;
12|  metaKey: string;
13|  jevKey?: string;
14|  sessionSecret: string;
15|  ipSalt: string;
16|  spendCapMicro: number;
17|}
18|
19|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
20|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
21|
22|// The uploads token is its own private store: the image store is public
23|// and a store's access mode is fixed at creation, so private puts would
24|// fail against it. Never fall back to the public store.
25|const REQUIRED = [
26|  "UPLOADS_BLOB_READ_WRITE_TOKEN",
27|  "META_API_KEY",
28|  "SESSION_SECRET",
29|  "IP_HASH_SALT",
30|] as const;
31|
32|export function readUploadEnv(from: NodeJS.ProcessEnv = process.env): UploadEnv {
33|  const candidate = usable(from.UPSTASH_REDIS_REST_URL) ?? usable(from.KV_REST_API_URL);
34|  const upstashUrl = candidate?.startsWith("https://") ? candidate : undefined;
35|  const upstashToken = usable(from.UPSTASH_REDIS_REST_TOKEN) ?? usable(from.KV_REST_API_TOKEN);
36|  const missing = [
37|    upstashUrl ? null : URL_NAMES,
38|    upstashToken ? null : TOKEN_NAMES,
39|    ...REQUIRED.filter((k) => !usable(from[k])),
40|  ].filter((m): m is string => m !== null);
41|  if (missing.length > 0) throw new Error(`missing upload env: ${missing.join(",")}`);
42|  const jevKey = usable(from.JEV_API_KEY);
43|  return {
44|    upstashUrl: upstashUrl as string,
45|    upstashToken: upstashToken as string,
46|    uploadsToken: from.UPLOADS_BLOB_READ_WRITE_TOKEN as string,
47|    metaKey: from.META_API_KEY as string,
48|    ...(jevKey ? { jevKey } : {}),
49|    sessionSecret: from.SESSION_SECRET as string,
50|    ipSalt: from.IP_HASH_SALT as string,
51|    spendCapMicro: Math.round(parseCapUsd(from.SPEND_CAP_USD, 10) * 1_000_000),
52|    ...turnstilePair(from),
53|  };
